             x26 x27 x28 x29 x30 x31)
        F (Z_to_bv 64 0x83358) fc None m (seg_rom asegs)).

  Lemma c1aA_inner : forall f s dt m1 mC r (x5 x6 x7 x13 x18 x20 x21 x22 x23 x26 x27 x28 x29 x30 x31 : word),
    fill_for_weight f dt (start + (s - b)) s e nb tl 0 1 sorted = Ok r ->
    Z.of_nat f = e - s + 1 -> b <= s < e -> INV m1 dt -> rw_cells asegs m1 (SPA + 288) [C8 (Z_to_bv 64 e)] ->
    munch [(DT + 4, DT + 4 + 4 * Z.of_nat ncells)] mC m1 -> wmono asegs mC m1 ->
    (forall m2 dt' (y1 y5 y6 y7 y10 y11 y12 y13 y14 y15 y16 y17 y18 y19 y20 y21 y22 y23 y25 y26 y27 y28 y29 y30 y31 : word),
       r = (dt', start + (e - b)) -> INV m2 dt' -> rw_cells asegs m2 (SPA + 288) [C8 (Z_to_bv 64 e)] ->
       munch [(DT + 4, DT + 4 + 4 * Z.of_nat ncells)] mC m2 -> wmono asegs mC m2 ->
       evtF asegs RNG Q (x2nextA SP SPA gp tp F fc m2 y1 y5 y6 y7 y10 y11 y12 y13 y14 y15 y16 y17 y18 y19 y20 y21 y22 y23
                           y25 y26 y27 y28 y29 y30 y31)) ->
    evtF asegs RNG Q (LH s m1 x5 x6 x7 x13 x18 x20 x21 x22 x23 x26 x27 x28 x29 x30 x31).
